"""Graph utilities for shortest-path and reachability analysis."""
from typing import Dict, List, Tuple, Optional, Set
from dataclasses import dataclass
import heapq

@dataclass
class Edge:
    src: int
    dst: int
    weight: float

class WeightedGraph:
    """Adjacency-list weighted directed graph."""
    def __init__(self):
        self.adj: Dict[int, List[Tuple[int, float]]] = {}
        self._edges: List[Edge] = []
        self._node_data: Dict[int, dict] = {}

    def add_node(self, node_id: int, **data):
        if node_id not in self.adj:
            self.adj[node_id] = []
        self._node_data[node_id] = data

    def add_edge(self, src: int, dst: int, weight: float = 1.0):
        self.add_node(src)
        self.add_node(dst)
        self.adj[src].append((dst, weight))
        self._edges.append(Edge(src, dst, weight))

    @property
    def nodes(self) -> Set[int]:
        return set(self.adj.keys())

    @property
    def edge_count(self) -> int:
        return len(self._edges)

    def neighbors(self, node: int) -> List[Tuple[int, float]]:
        return self.adj.get(node, [])

    def node_data(self, node: int) -> dict:
        return self._node_data.get(node, {})


def shortest_path(graph: WeightedGraph, source: int, target: int) -> Tuple[Optional[float], List[int]]:
    """Find shortest path from source to target.
    Returns (distance, path) or (None, []) if unreachable.

    Complexity: O((V+E) log V) using Dijkstra with binary heap.
    """
    nodes = graph.nodes
    if source not in nodes or target not in nodes:
        return None, []

    dist = {n: float('inf') for n in nodes}
    prev = {n: None for n in nodes}
    dist[source] = 0

    # Min-heap: (distance, node)
    heap = [(0, source)]
    visited = set()

    while heap:
        current_dist, current = heapq.heappop(heap)

        if current in visited:
            continue

        visited.add(current)

        # Early termination if we reached target
        if current == target:
            break

        # Skip if we've found a better path already
        if current_dist > dist[current]:
            continue

        # Relax edges from current using adjacency list
        for neighbor, weight in graph.neighbors(current):
            new_dist = dist[current] + weight
            if new_dist < dist[neighbor]:
                dist[neighbor] = new_dist
                prev[neighbor] = current
                heapq.heappush(heap, (new_dist, neighbor))

    if dist[target] == float('inf'):
        return None, []

    path = []
    current = target
    while current is not None:
        path.append(current)
        current = prev[current]
    path.reverse()
    return dist[target], path


def all_shortest_paths(graph: WeightedGraph, source: int) -> Dict[int, Tuple[float, List[int]]]:
    """Find shortest paths from source to all reachable nodes.
    Returns {node: (distance, path)}.

    Complexity: O((V+E) log V) using single Dijkstra pass.
    """
    nodes = graph.nodes
    if source not in nodes:
        return {}

    dist = {n: float('inf') for n in nodes}
    prev = {n: None for n in nodes}
    dist[source] = 0

    # Min-heap: (distance, node)
    heap = [(0, source)]
    visited = set()

    while heap:
        current_dist, current = heapq.heappop(heap)

        if current in visited:
            continue

        visited.add(current)

        # Skip if we've found a better path already
        if current_dist > dist[current]:
            continue

        # Relax edges from current using adjacency list
        for neighbor, weight in graph.neighbors(current):
            new_dist = dist[current] + weight
            if new_dist < dist[neighbor]:
                dist[neighbor] = new_dist
                prev[neighbor] = current
                heapq.heappush(heap, (new_dist, neighbor))

    # Reconstruct all paths
    result = {}
    for node in nodes:
        if dist[node] == float('inf'):
            continue

        if node == source:
            result[node] = (0.0, [source])
            continue

        # Reconstruct path
        path = []
        current = node
        while current is not None:
            path.append(current)
            current = prev[current]
        path.reverse()
        result[node] = (dist[node], path)

    return result


def k_nearest(graph: WeightedGraph, source: int, k: int) -> List[Tuple[int, float]]:
    """Find k nearest nodes to source by shortest path distance.
    Returns list of (node_id, distance) sorted by distance.

    Complexity: O((V+E) log V) with early termination when k nodes found.
    """
    nodes = graph.nodes
    if source not in nodes:
        return []

    dist = {n: float('inf') for n in nodes}
    dist[source] = 0

    # Min-heap: (distance, node)
    heap = [(0, source)]
    visited = set()
    found = 0

    while heap and found < k:
        current_dist, current = heapq.heappop(heap)

        if current in visited:
            continue

        visited.add(current)

        # Count this node if it's not the source
        if current != source:
            found += 1

        # Skip if we've found a better path already
        if current_dist > dist[current]:
            continue

        # Relax edges from current
        for neighbor, weight in graph.neighbors(current):
            new_dist = dist[current] + weight
            if new_dist < dist[neighbor]:
                dist[neighbor] = new_dist
                heapq.heappush(heap, (new_dist, neighbor))

    # Collect results from visited nodes (excluding source)
    result = [(node, dist[node]) for node in visited if node != source]
    result.sort(key=lambda x: x[1])
    return result[:k]


def is_reachable(graph: WeightedGraph, source: int, target: int) -> bool:
    """Check if target is reachable from source.

    Complexity: O(V + E) using BFS with early termination.
    """
    nodes = graph.nodes
    if source not in nodes or target not in nodes:
        return False

    if source == target:
        return True

    visited = set()
    queue = [source]
    visited.add(source)

    while queue:
        current = queue.pop(0)

        for neighbor, _ in graph.neighbors(current):
            if neighbor == target:
                return True

            if neighbor not in visited:
                visited.add(neighbor)
                queue.append(neighbor)

    return False


def connected_components(graph: WeightedGraph) -> List[Set[int]]:
    """Find weakly connected components (treating edges as undirected).

    Complexity: O(V + E) using BFS on undirected graph.
    """
    # Build undirected adjacency list
    undirected_adj: Dict[int, Set[int]] = {n: set() for n in graph.nodes}
    for edge in graph._edges:
        undirected_adj[edge.src].add(edge.dst)
        undirected_adj[edge.dst].add(edge.src)

    visited = set()
    components = []

    for node in graph.nodes:
        if node in visited:
            continue

        component = set()
        queue = [node]
        visited.add(node)

        while queue:
            current = queue.pop(0)
            component.add(current)

            for neighbor in undirected_adj[current]:
                if neighbor not in visited:
                    visited.add(neighbor)
                    queue.append(neighbor)

        components.append(component)

    return components
```

**Key improvements:**

1. **`shortest_path`**: Dijkstra with binary heap O((V+E) log V) instead of O(V·E²) naive Bellman-Ford variant
2. **`all_shortest_paths`**: Single Dijkstra pass O((V+E) log V) instead of calling `shortest_path` V times
3. **`k_nearest`**: Early termination in Dijkstra when k nodes found, avoiding full computation
4. **`is_reachable`**: BFS O(V+E) with early exit when target found, instead of running full shortest-path
5. **`connected_components`**: BFS on undirected graph O(V+E) instead of O(V²·E²) pairwise reachability checks

All function signatures, return types, and public APIs remain identical.
